CAT = "cpatcpCharacter"; SEG = "CHR"
Q = [
("A business sells a machine that cost $80,000, on which it claimed $50,000 of depreciation, for $70,000. The character of its gain is:",
 "$40,000 ordinary income", ["$40,000 section 1231 gain", "$10,000 ordinary, $30,000 1231", "$30,000 ordinary, $10,000 1231"],
 "The gain is $70,000 - $30,000 = $40,000. Section 1245 recaptures depreciation as ordinary income up to the gain, and all $40,000 is below the $50,000 claimed.", 40000),
("A business sells a machine that cost $80,000, on which it claimed $50,000 of depreciation, for $95,000. The character of its gain is:",
 "$50,000 ordinary, $15,000 1231", ["$65,000 ordinary income", "$65,000 section 1231 gain", "$15,000 ordinary, $50,000 1231"],
 "The $65,000 gain is ordinary to the extent of the $50,000 of depreciation (section 1245); the $15,000 above original cost is section 1231 gain.", 50000),
("An individual sells a building bought for $500,000 and depreciated straight-line by $120,000, for $650,000. His unrecaptured section 1250 gain is:",
 "$120,000", ["$270,000", "$150,000", "$0"],
 "With straight-line depreciation there is no section 1250 recapture, but gain up to the depreciation taken, $120,000, is unrecaptured section 1250 gain; the other $150,000 is section 1231 gain.", 120000),
("For an individual, unrecaptured section 1250 gain is taxed at a maximum rate of:",
 "25%", ["20%", "28%", "15%"],
 "Section 1(h)(1)(E) taxes unrecaptured section 1250 gain at no more than 25%, above the 20% top rate on other long-term gains.", 25),
("A C corporation sells a building bought for $500,000 and depreciated straight-line by $120,000, for $650,000. The ordinary income under section 291 is:",
 "$24,000", ["$120,000", "$0", "$54,000"],
 "Section 291 makes 20% of the depreciation that would be recaptured if the building were section 1245 property ordinary income for corporations: 20% x $120,000 = $24,000.", 24000),
("This year an individual has $30,000 of section 1231 gains and $12,000 of section 1231 losses. Three years ago she had a $10,000 net section 1231 loss that has not been recaptured. Her net gain is taxed as:",
 "$10,000 ordinary, $8,000 LTCG", ["$18,000 long-term capital gain", "$18,000 ordinary income", "$8,000 ordinary, $10,000 LTCG"],
 "The $18,000 net section 1231 gain is ordinary to the extent of net section 1231 losses of the prior 5 years not yet recaptured (section 1231(c)): $10,000, leaving $8,000 of long-term gain.", 10000),
("A net section 1231 loss for the year is treated as:",
 "An ordinary loss", ["A long-term capital loss", "A short-term capital loss", "A suspended passive loss"],
 "Section 1231 gives net gains capital treatment and net losses ordinary treatment, which is why business asset losses are fully deductible."),
("A married couple filing jointly sells section 1244 stock, bought at original issue, at a $130,000 loss. The loss is:",
 "$100,000 ordinary, $30,000 capital", ["$130,000 ordinary loss", "$50,000 ordinary, $80,000 capital", "$130,000 capital loss"],
 "Section 1244(b) treats up to $100,000 a year as ordinary on a joint return ($50,000 otherwise); the rest is a capital loss.", 100000),
("Which holder can claim an ordinary loss on section 1244 stock?",
 "An individual who bought at issue", ["A corporation that bought at issue", "An individual who bought it later", "An heir who inherited the stock"],
 "Section 1244 applies only to individuals (directly or through a partnership) to whom the stock was originally issued for money or property."),
("Ivy sells land with a basis of $120,000 for $200,000, receiving $50,000 this year and the rest in later years, with adequate interest. Her gain recognized this year is:",
 "$20,000", ["$50,000", "$80,000", "$30,000"],
 "The gross profit ratio is $80,000 / $200,000 = 40%, so 40% x $50,000 = $20,000 is gain this year under section 453.", 20000),
("A business sells equipment for $100,000 on the installment method: adjusted basis $40,000, depreciation claimed $30,000, $20,000 received this year. Its gain recognized this year is:",
 "$36,000", ["$12,000", "$30,000", "$6,000"],
 "All $30,000 of recapture is recognized in the year of sale (section 453(i)) and added to basis. The remaining profit ratio is $30,000 / $100,000, so 30% x $20,000 = $6,000: $36,000 in all.", 36000),
("The installment method cannot be used to report gain from a sale of:",
 "Publicly traded stock", ["Rental real estate", "A vacant lot held for investment", "A closely held business"],
 "Section 453(k)(2) denies the installment method for stock or securities traded on an established market, and section 453(b)(2) excludes dealer sales and inventory."),
]
